import{c as t,Q as r,j as a,m as o}from"./chunks/framework.hhGiamYR.js";const d=JSON.parse('{"title":"让你的文字像当面说话——关于写作，我唯一确定的规则","description":"","frontmatter":{"date":"2026-08-23T00:00:00.000Z","title":"让你的文字像当面说话——关于写作，我唯一确定的规则"},"headers":[],"relativePath":"research/write-as-if-speaking/index.md","filePath":"research/write-as-if-speaking/index.md"}'),l={name:"research/write-as-if-speaking/index.md"};function i(p,e,s,n,u,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="让你的文字像当面说话" tabindex="-1">让你的文字像当面说话 <a class="header-anchor" href="#让你的文字像当面说话" aria-label="Permalink to &quot;让你的文字像当面说话&quot;">​</a></h1><p><em>来自佛罗伦萨的一封信</em></p><p>朋友：</p><p>此刻我坐在圣卡夏诺乡下的农庄里给你写这封信。若你期待我谈君主的狮狐之喻，或者命运女神如何夺走我们一半的行动，那你要失望了——今天我只想谈一件更小、却也更难的事：<strong>动笔</strong>。</p><p>让我先讲一桩旧事。1513年8月4日，我给我的外甥乔瓦尼·韦尔纳奇写了一封信。他那时远在黎凡特做布匹生意，寄回来的报告惹得洛伦佐·马基雅维利很不高兴。我自己的日子也不好过——就在那封信里，我顺带提了一句：玛丽埃塔刚生下的女孩，三天后夭折了。可我没在这件事上停留，话头一转，还是回到他那些写砸了的报告上。</p><blockquote><p>📖 <strong>原文</strong>：《书信集》书信217，致乔瓦尼·韦尔纳奇 &quot;我劝你写信给你的生意伙伴时，要写得清楚一些，让他们无论何时收到你的信，由于你写得十分详尽，他们都会觉得，就仿佛你当着他们的面说话一样。&quot;</p><ul><li>全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/letters/1510-1513.md" target="_blank" rel="noreferrer">machiavelli/letters/1510-1513.md</a></li></ul></blockquote><p>这就是我关于写作的全部信念，浓缩成一句话。文字是缺席者的替身：你人不在场，信到了，你的字就得替你站在那里，替你把话一句句说完。写不清楚，等于派了一个哑巴去替你谈判，还指望对方体谅你的苦衷。没有人会体谅。收信人只看到一张纸，纸上有什么，他就信什么。</p><p>那么，&quot;如当面说话&quot;怎样才能做到？靠的不是辞藻，而是<strong>先把读者脑子里的问题想在前头</strong>。我一生写了十四年的外交急件，给十人委员会、给旗手、给那些等得不耐烦的雇主。我的办法从来一样：下笔之前，先问自己——读这封信的人，此刻最想知道什么？他最怕什么？他会在哪一句话上起疑心？</p><blockquote><p>📖 <strong>原文</strong>：《书信集》书信213，致弗朗切斯科·韦托里 &quot;明智之人永远要防患于未然，未雨绸缪以扬善抑恶，所以就让我设身处地为教皇仔细审视一下，现在究竟有什么好怕的、可采取什么补救措施。&quot;</p><ul><li>全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/letters/1510-1513.md" target="_blank" rel="noreferrer">machiavelli/letters/1510-1513.md</a></li></ul></blockquote><p>那封信里我谈的是教皇的处境，可这套&quot;设身处地&quot;的功夫，用在写作上同样灵验。你不必是教皇，也不必是我的外甥——但凡你要把一件事写给另一个人看，先把自己放进他的椅子，用他的眼睛扫一遍你的文字。他在哪会停下？在哪会皱眉？在哪会骂一句&quot;这到底要说什么&quot;？把这些地方堵上，你的信就活了。</p><p>还有一句要紧的：写得详尽，不等于写得啰嗦。我劝乔瓦尼&quot;写得十分详尽&quot;，是要他把该交代的情况都交代了——货在哪、钱多少、何时到、有何风险——而不是要他把寒暄铺满三页纸。每句话都得有一个目的，都得指向一个结论。做不到这一点的字，删掉。</p><p>我身体很好，但别的方面糟透了——不过那是另一封信的事。眼下你只需记住这一条：动笔时，假装那人就坐在你对面。你当他面不敢含糊其辞的话，落到纸上也别含糊。</p><p><em>尼科洛·马基雅维利，圣卡夏诺</em></p>',13)])])}const h=t(l,[["render",i]]);export{d as __pageData,h as default};
